import java.util.*;

class Solution {
    public int maxKTrips(int k, int[] prices) {
        if (k == 0) return 0;
        int[] buy = new int[k + 1], sell = new int[k + 1];
        Arrays.fill(buy, Integer.MIN_VALUE / 2);   // "impossible" without overflow
        for (int p : prices) {
            for (int j = 1; j <= k; j++) {
                buy[j] = Math.max(buy[j], sell[j - 1] - p);  // start trip j after finishing j-1
                sell[j] = Math.max(sell[j], buy[j] + p);     // finish trip j today
            }
        }
        return sell[k];
    }
}

