class Solution:
    def maxKTrips(self, k: int, prices: List[int]) -> int:
        buy = [-inf] * (k + 1)
        sell = [0] * (k + 1)
        for p in prices:
            for j in range(1, k + 1):
                buy[j] = max(buy[j], sell[j - 1] - p)
                sell[j] = max(sell[j], buy[j] + p)
        return sell[k]

