function maxKTrips(k, prices) {
  const n = prices.length;
  let prev = new Array(n).fill(0);
  for (let t = 1; t <= k; t++) {
    const cur = new Array(n).fill(0);
    let bestBuy = -prices[0];
    for (let i = 1; i < n; i++) {
      cur[i] = Math.max(cur[i-1], prices[i] + bestBuy);
      bestBuy = Math.max(bestBuy, prev[i] - prices[i]);
    }
    prev = cur;
  }
  return prev[n-1];
}
